svg('modes',[[('Shape now','Immediate, bounded controls'),('Create for me','Intent + taste + duration')],[('Level / brightness / space','Prepared audio keeps playing'),('Generating / reviewing','Cancel or return later')],[('Prepare variation','Safe handoff when approved'),('Ready to preview','User chooses when to play')]],'Soulfire masterbrand / Current feature identity / no autoplay')
svg('controls',[[('Direct control','Gain, EQ, reverb, timer')],[('Musical request','Tempo, palette, feel, instrumental')],[('Candidate + adherence check','Confidence plus human review')],[('Approved replacement','No guaranteed stems or exact notes')]],'A request is not a deterministic composition constraint.')
svg('pipeline',[[('Policy recipe','Version + preferences'),('Turbo worker','Bounded job + seed')],[('Hard audio checks','Decode / peak / duration'),('Confidence checks','Tempo / leakage / seams')],[('Listening review','Fit / artifacts / resemblance')],[('Promote atomically','Manifest + approved assets')]],'Cancel invalidates job version; rejected audio never becomes filler.')
svg('audio',[[('Approved segments','Prepared and buffered')],[('EQ + space','Bounded, gain compensated'),('Separate ambience','Only a real separate track')],[('Master + limiter','Ramped changes / headroom')],[('One audio owner','Stop remains independent of model')]],'Next segment late? Tested loop or graceful fade to quiet.')
