def special(name,body,h):
 (R/'diagrams'/f'{name}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="{h}" viewBox="0 0 1000 {h}"><rect width="1000" height="{h}" rx="20" fill="#FAF7EF"/>'+body+'</svg>')
