b+='<rect x="544" y="389" width="245" height="39" rx="18" fill="#E9C883"/><text x="666" y="414" text-anchor="middle" font-family="Arial" font-size="17" fill="#183F3B">Prepare my Current</text><text x="500" y="485" text-anchor="middle" font-family="Arial" font-size="17" fill="#61746E">Illustrated concept only / new music never autoplays</text>'
