# HTML is self-contained editable review artifact
parts=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Current - music evolution</title><style>body{background:#eeeae0;color:#183f3b;font:17px/1.55 Arial;margin:0}main{max-width:960px;margin:auto}article{background:#faf7ef;padding:60px;margin:28px 0;border-radius:18px}h1{font:44px Georgia;margin:8px 0 20px}h2{font-size:21px;margin:24px 0 6px}.k{letter-spacing:2px;font-size:12px}.lead{font-size:22px;color:#61746e}svg{width:100%;height:auto;margin-top:24px}a{color:#285f56;overflow-wrap:anywhere}@media print{article{break-after:page;margin:0;padding:35px}body{background:white}}</style><main>']
for p in pages:
 parts.append(f'<article><div class="k">SOULFIRE / {p["kicker"]}</div><h1>{html.escape(p["title"])}</h1><p class="lead">{html.escape(p["lead"])}</p>')
 for t,b in p['sections']:
  bhtml=f'<a href="{html.escape(b)}">{html.escape(b)}</a>' if b.startswith('https://') else html.escape(b)
  parts.append(f'<h2>{html.escape(t)}</h2><p>{bhtml}</p>')
 if p['diagram']:parts.append((R/'diagrams'/f'{p["diagram"]}.svg').read_text())
 parts.append('<small>PROPOSED / 29 OCT 2026 / NO APP CHANGES</small></article>')
